function updateTraditional(){for(const b of root.querySelectorAll('#gc-houses [data-house]')){b.querySelectorAll('.gochar-badge').forEach(n=>n.remove());if(timeState==='birth'||!transit)continue;const id=Number(b.dataset.house),names=transit.planets.filter(p=>p.house===id).map(p=>catalog[p.id].name);if(names.length){const badge=document.createElement('span');badge.className='gochar-badge';badge.textContent='Gochar: '+names.join(' · ');b.append(badge);}}}
