 for(const b of root.querySelectorAll('[data-time]'))b.setAttribute('aria-pressed',String(b.dataset.time===timeState));$('timeline-controls').hidden=timeState!=='timeline';$('gochar-stage').hidden=timeState==='birth';$('gochar-date').value=new Date(nowMS).toISOString().slice(0,19);$('gochar-utc').textContent=timeState==='birth'?'Birth UTC: '+natal.utc:'Calculated Gochar UTC: '+(transit?.utc??'Loading…');
