 updateTraditional();const showArt=['devas','bhava'].includes(mode);$('gochar-residence').hidden=!showArt;$('space-select-label').hidden=mode!=='planetary';
 const p=transit?.planets.find(p=>p.id===selected);if(p){$('rig-context').textContent=`TRANSIT ${catalog[selected].name.toUpperCase()} · H${p.house} · ${signs[p.sign]} · natal occupants remain above`;if(mode==='bhava')$('gochar-residence').style.backgroundImage=`url('${catalog[selected].worldBase??'/studio-assets/'}bhava-${p.house}-world-v4c.webp')`;else $('gochar-residence').style.backgroundImage='none';}
