async function setRig(){if(!catalog)return;rig?.destroy();$('gochar-rig').replaceChildren();const entry=catalog[selected];$('gochar-rig').setAttribute('viewBox',`-80 -50 ${entry.width+160} ${entry.height+100}`);rig=createMobilityPainter($('gochar-rig'),entry);rig.update(0,{moving:false});$('gochar-audio-credit').textContent=entry.audioCredit??'Vulture sound is unavailable: no verified natural recording selected. No substitute species is played.';try{await audio.focus(selected);}catch{$('gochar-status').textContent='Animal audio could not load; the calculated chart remains available.';}}
